import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../core/services/api.service';

@Component({
  selector: 'app-admin-tours',
  standalone: true,
  imports: [CommonModule, RouterModule, FormsModule],
  template: `
    <div class="page-header"><div class="container"><h2>Quản lý Tours</h2></div></div>
    <section class="section">
      <div class="container">
        <div style="margin-bottom:1.5rem;display:flex;justify-content:space-between;align-items:center;">
          <input type="text" class="form-control" style="max-width:300px;" [(ngModel)]="search" (ngModelChange)="load()" placeholder="Tìm kiếm...">
          <a routerLink="/admin/tours/create" class="btn btn-primary"><span class="material-icons">add</span> Thêm mới</a>
        </div>
        <div class="loading-spinner" *ngIf="loading"><div class="spinner"></div></div>
        <table class="data-table" *ngIf="!loading">
          <thead><tr><th>Tên</th><th>Thời gian</th><th>Giá</th><th>Trạng thái</th><th>Hành động</th></tr></thead>
          <tbody>
            <tr *ngFor="let t of data">
              <td>{{ t.name }}</td>
              <td>{{ t.duration }}</td>
              <td>{{ t.discountPrice || t.price | number:'1.0-0' }}đ</td>
              <td><span class="badge" [class.badge-success]="t.isActive" [class.badge-danger]="!t.isActive">{{ t.isActive ? 'Active' : 'Inactive' }}</span></td>
              <td><a [routerLink]="['/admin/tours/edit', t.id]" class="btn btn-sm btn-outline">Sửa</a> <button class="btn btn-sm btn-danger" (click)="delete(t.id)">Xóa</button></td>
            </tr>
          </tbody>
        </table>
      </div>
    </section>
  `
})
export class AdminToursComponent implements OnInit {
  data: any[] = [];
  loading = true;
  search = '';
  constructor(private api: ApiService) {}
  ngOnInit() { this.load(); }
  load() {
    this.loading = true;
    const params: any = {};
    if (this.search) params.search = this.search;
    this.api.getTours(params).subscribe(res => { this.data = res.data; this.loading = false; }, () => { this.loading = false; });
  }
  delete(id: string) { if (confirm('Xác nhận xóa?')) this.api.deleteTour(id).subscribe(() => this.load()); }
}
